('follow_up_switch', '客户跟进提醒', 'radio', '', @followUpConfigPid, '', '1=&gt;开启\n0=&gt;关闭', 0, '', 0, 0, 0, '开关开启后，根据跟进周期对业务员进行系统跟进提醒', 0, 0, '', 1, '2023-11-22 08:50:25', '2024-01-19 08:27:24'),
