('follow_up_unsettled', '客户状态暂未成交提醒周期', 'text', 'number', @followUpConfigPid, '', '', 0, '', 0, 0, '', '用于设置暂未成交状态的客户多少天需要跟进一次', 0, 0, '', 1, '2023-11-22 08:50:25', '2024-01-19 08:27:24'),
